package main

import "fmt"

func main() {
	// One backing array, two headers sharing it.
	a := make([]int, 2, 4)
	a[0], a[1] = 1, 2
	b := a[:2]

	// b has cap 2 (a[:2] keeps the array, cap = 4 - 0 = 4? no:
	// b := a[:2] gives cap 2). appending to b does not fit and
	// reallocates — but the danger case is a[:0] style headers
	// that DO have spare capacity, so appending mutates a.
	danger := a[:0] // len 0, cap 4 — shares the whole array
	danger = append(danger, 100)

	fmt.Println(a) // [100, 2]: a changed! The append wrote into
	// the shared backing array because danger had spare capacity.

	// The bug: a local helper that does append(s[:0], ...) on a
	// caller's slice silently corrupts the caller's data.
}

package main

import "fmt"

func main() {
	a := make([]int, 2, 4)
	a[0], a[1] = 1, 2

	// Take a FULL copy so the helper cannot write into a's array.
	copyOfA := append([]int(nil), a[:2]...)
	copyOfA = append(copyOfA, 100)

	fmt.Println(a, copyOfA) // [1 2] [1 2 100]

	// For retaining a small slice of a huge one, copying prevents
	// pinning the entire backing array in memory:
	big := make([]int, 1_000_000)
	// DO: keep := append([]int(nil), big[:3]...)  → 24 bytes
	// DON'T: keep := big[:3]  → pins 8MB backing array
	_ = big
}
